/* ---------- Voice orb ---------- */
/* a hands-free voice chat: an orb that swells with whoever is talking, the accent colour for you and violet for the agent, what
   was said under it, and mute and end below. Talking while muted says so, the way calls do */
.vor{position:relative;width:100%;max-width:380px;margin:0 auto;padding:16px;display:flex;flex-direction:column;gap:12px;--oc:var(--faint);--oc2:var(--muted)}
/* --oc is whoever is talking, --oc2 the second colour that flows through the orb with it */
.vor[data-m="listening"]{--oc:var(--accent);--oc2:color-mix(in srgb,var(--pl) 45%,var(--accent))}
.vor[data-m="speaking"]{--oc:var(--pl);--oc2:color-mix(in srgb,var(--accent) 45%,var(--pl))}
.vor[data-m="thinking"]{--oc:color-mix(in srgb,var(--accent) 50%,var(--pl));--oc2:var(--accent)}
.vor[data-m="muted"]{--oc:color-mix(in srgb,var(--muted) 55%,var(--faint));--oc2:var(--faint)}
.vor-top{display:flex;align-items:center;gap:8px;font-size:13px}
.vor-dot{width:8px;height:8px;border-radius:50%;background:var(--oc);transition:background .4s}
.vor[data-m="listening"] .vor-dot,.vor[data-m="speaking"] .vor-dot{animation:vor-pulse 1.4s var(--ease-io) infinite}
@keyframes vor-pulse{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--oc) 35%,transparent)}50%{box-shadow:0 0 0 5px transparent}}
.vor-t{margin-left:auto;font-size:12.5px}
.vor-orb{position:relative;width:112px;height:112px;margin:8px auto;--lv:0}
.vor-orb i{position:absolute;inset:0;border-radius:50%}
/* round in Blueprint too, where every other corner is square: like the turning loaders, its shape is what it says */
.vor .vor-orb i{border-radius:50%!important}
/* the glow: both colours turning slowly behind the orb and fading out from its edge (a mask, not a blur, so Blueprint keeps
   it too), brighter and wider the louder the voice */
.vor .vor-orb .vor-glow{inset:-30px;background:conic-gradient(from 0deg,var(--oc),var(--oc2),var(--oc));-webkit-mask:radial-gradient(closest-side,#000 48%,transparent);mask:radial-gradient(closest-side,#000 48%,transparent);opacity:calc(.3 + var(--lv) * .45);transform:scale(calc(.9 + var(--lv) * .3));animation:vor-spin 9s linear infinite;transition:opacity .4s}
.vor[data-m="idle"] .vor-orb .vor-glow,.vor[data-m="ended"] .vor-orb .vor-glow,.vor[data-m="muted"] .vor-orb .vor-glow{opacity:.16}
@keyframes vor-spin{to{rotate:360deg}}
.vor-core{overflow:hidden;background-color:color-mix(in srgb,var(--oc) 72%,var(--surface));background-image:radial-gradient(circle at 34% 28%,rgba(255,255,255,.42),rgba(255,255,255,0) 62%);box-shadow:inset 0 -8px 18px color-mix(in srgb,var(--oc) 30%,transparent),0 0 0 1px color-mix(in srgb,var(--oc) 20%,transparent);transform:scale(calc(.9 + var(--lv) * .14));transition:background-color .4s}
/* the flowing inside, drawn over the plain gradient once WebGL is there */
.vor-gl{position:absolute;inset:0;width:100%;height:100%;border-radius:50%;opacity:0;transition:opacity .4s}
.vor-gl.on{opacity:1}
/* reads the second colour as it eases from one speaker to the next */
.vor-pc{visibility:hidden;background:var(--oc2);transition:background .4s}
.vor-cap,.vor-mf,.vor-f{position:relative}
.vor[data-m="thinking"] .vor-core{animation:vor-br 1.6s var(--ease-io) infinite alternate}
@keyframes vor-br{from{transform:scale(.9)}to{transform:scale(.96)}}
@media (prefers-reduced-motion:reduce){.vor-glow{animation:none}}
.vor-cap{min-height:88px;display:flex;flex-direction:column;gap:2px;text-align:center}
.vor-who{font-size:12px;min-height:18px}
.vor-tx{margin:0;font-size:14px;line-height:1.6;color:var(--fg)}
.vor-tx.hint{color:var(--muted);font-size:13px}
.vor-tx .w{animation:vor-w .45s var(--ease) both}
@keyframes vor-w{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.vor-mw{display:flex;align-items:center;gap:10px;padding:8px 8px 8px 12px;border-radius:12px;background:var(--warn-bg)}
.vor-mw p{margin:0;flex:1;display:flex;gap:8px;font-size:13px;line-height:1.45;color:var(--fg)}
.vor-mw p svg{color:var(--warn);flex:none;margin-top:3px}
.vor-mw .pill,.vor-done .pill{background:var(--surface);color:var(--fg);box-shadow:var(--shadow)}
.vor-f{display:flex;align-items:center;gap:8px;min-height:32px}
.vor-f .sp{flex:1}
.vor:not(.on) .vor-f{justify-content:center}
.vor:not(.on) .vor-mute,.vor:not(.on) .vor-end,.vor:not(.on) .vor-f .sp,.vor.on .vor-go{display:none}
.vor-mute{position:relative}
.vor-mute[aria-pressed="true"]{background:var(--bad-bg);color:var(--bad);box-shadow:none}
/* the slash across the microphone once it is muted */
.vor-mute::after{content:"";position:absolute;left:50%;top:50%;width:1.5px;height:18px;margin:-9px 0 0 -.75px;border-radius:2px;background:currentColor;transform:rotate(-45deg) scaleY(0);transition:transform .25s var(--ease)}
.vor-mute[aria-pressed="true"]::after{transform:rotate(-45deg) scaleY(1)}
.vor-end{background:var(--bad);color:var(--on-ink)}
.vor-end:hover{background:color-mix(in srgb,var(--bad) 86%,#000)}
.vor-done{display:flex;align-items:center;gap:12px;padding:10px 10px 10px 12px;border-radius:12px;background:var(--chip);font-size:13.5px}
.vor-done>svg{color:var(--fg2);flex:none}
.vor-done .t{flex:1;min-width:0;display:flex;flex-direction:column}
.vor-done .t span{font-size:13px}

DM.def('voice-orb', (r, c) => {
  const IC = { warn:I('alert','xs'), mic:I('mic','xs'), micm:I('mic') };
  r.innerHTML = r.innerHTML.replace(/\{(\w+)\}/g, (m, k) => IC[k] || m);
  const root = $('.vor', r), orb = $('.vor-orb', r), st = $('.vor-st', r), tm = $('.vor-t', r), who = $('.vor-who', r), tx = $('.vor-tx', r), mf = $('.vor-mf', r), f = $('.vor-f', r), mute = $('.vor-mute', r);
  // what is said, turn by turn. The demo plays it as a script: it never uses the microphone or makes a sound
  const TURNS = [['You', 'Make the yearly price the default on the pricing page.'], ['Agent', 'Done. Yearly is now the default on all three plans in Pricing v4.'], ['You', 'Show the yearly saving in green too.'], ['Agent', 'Added. The saving shows in green under each yearly price.']];
  const HINT = 'Talk to the agent about Pricing v4', LABEL = { idle:'Ready', listening:'Listening', thinking:'Thinking', speaking:'Speaking', muted:'Muted', ended:'Ended' };
  let mode = 'idle', muted = false, talking = false, said = 0, secs = 0, run = 0, done = null, lv = 0;
  const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  // muted only changes how listening looks: the agent can still think and speak
  const show = () => { const m = muted && mode === 'listening' ? 'muted' : mode; if (root.dataset.m !== m){ root.dataset.m = m; swap(st, LABEL[m]); } };
  const set = m => { mode = m; show(); };
  const notice = on => { mf.classList.toggle('shut', !on); mf.inert = !on; };
  notice(false);
  // inside the orb, light flows in the two colours of whoever is talking, faster and brighter as they get louder: a small
  // WebGL shader of warped noise, shaded as a sphere. Without WebGL the core keeps its plain gradient
  const paint = orbShader($('.vor-gl', orb), c), dot = $('.vor-dot', r), pc = $('.vor-pc', orb);
  let seen = true, flow = 0, last = 0;
  if (paint && 'IntersectionObserver' in window){ const io = new IntersectionObserver(e => { seen = e[0].isIntersecting; }); io.observe(orb); c.offs.push(() => io.disconnect()); }
  const draw = t => paint && paint(t, lv, getComputedStyle(dot).backgroundColor, getComputedStyle(pc).backgroundColor);
  // the orb follows a level: a made-up voice while someone talks, a faint idle while it listens
  if (!REDUCE) c.loop(t => {
    const to = talking ? .5 + .28 * Math.sin(t / 90) * Math.sin(t / 233) + .16 * Math.sin(t / 57) : mode === 'listening' && !muted ? .05 + .03 * Math.sin(t / 420) : 0;
    lv += (Math.max(0, to) - lv) * .18; orb.style.setProperty('--lv', lv.toFixed(3));
    flow += Math.min(50, t - (last || t)) * (1 + lv * 2.5); last = t;
    if (seen) draw(flow);
  });
  // with reduced motion it is still: one frame, drawn again when the colours change
  else if (paint){ draw(0); new MutationObserver(() => c.later(450, () => draw(0))).observe(root, { attributes:true, attributeFilter:['data-m'] }); }
  c.every(1000, () => { if (mode !== 'idle' && mode !== 'ended'){ secs++; tm.textContent = fmt(secs); } });
  async function say(name, line, ms, id){
    swap(who, name); tx.classList.remove('hint'); tx.innerHTML = ''; talking = true;
    for (const w of line.split(' ')){ if (id !== run) return; tx.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await c.wait(ms); }
    talking = false;
  }
  async function talk(id){
    for (const [name, line] of TURNS){
      if (name === 'You'){
        set('listening'); await c.wait(1200); if (id !== run) return;
        // they start talking while muted: say so, and wait for them to unmute
        if (muted){ notice(true); while (muted){ await c.wait(100); if (id !== run) return; } await c.wait(400); if (id !== run) return; }
        await say(name, line, 230, id); if (id !== run) return;
        set('thinking'); await c.wait(1300);
      } else { set('speaking'); await say(name, line, 190, id); if (id !== run) return; set('listening'); }
      said++;
    }
  }
  function start(){
    const id = ++run; said = 0; secs = 0; tm.textContent = fmt(0);
    if (done){ done.remove(); done = null; } f.hidden = false; root.classList.add('on');
    c.run(() => talk(id));
  }
  function setMuted(on){
    muted = on; mute.setAttribute('aria-pressed', on); mute.dataset.tip = on ? 'Unmute' : 'Mute';
    if (!on) notice(false); show();
  }
  $('.vor-go', r).onclick = start;
  mute.onclick = () => setMuted(!muted);
  $('.vor-un', r).onclick = () => setMuted(false);
  $('.vor-end', r).onclick = () => {
    run++; talking = false; notice(false); set('ended'); root.classList.remove('on'); f.hidden = true;
    done = html(`<div class="vor-done">${I('ok')}<span class="t">Voice chat ended<span class="muted">${fmt(secs)} · Transcript saved</span></span><button class="pill sm">Start again</button></div>`);
    root.appendChild(done); enter(done);
    $('button', done).onclick = () => { setMuted(false); swap(who, ''); tx.classList.add('hint'); tx.textContent = HINT; start(); };
  };
  // the preview's story: start, mute while the agent answers, talk while muted, unmute and go on, then end
  c.story(async s => {
    await s.beat(3); await s.tap($('.vor-go', r)); s.away();
    await s.until(() => mode === 'speaking'); await s.beat(3); await s.tap(mute); s.away();
    await s.until(() => !mf.classList.contains('shut')); await s.beat(4);
    await s.tap($('.vor-un', r)); s.away();
    await s.until(() => said === TURNS.length); await s.beat(3);
    await s.tap($('.vor-end', r)); s.away(); await s.beat(1);
  });
});
